            ['start_time'=>99.320,'end_time'=>99.860,'target_text'=>'a.m.','source_text'=>'pagi.','order'=>36],
            ['start_time'=>99.960,'end_time'=>101.020,'target_text'=>'It\'s almost lunch time.','source_text'=>'Hampir waktu makan tengahari.','order'=>37],
            ['start_time'=>101.120,'end_time'=>104.640,'target_text'=>'I haven\'t eaten anything yet.','source_text'=>'Saya belum makan apa-apa lagi.','order'=>38],
            ['start_time'=>105.560,'end_time'=>107.060,'target_text'=>'Oh, excuse me.','source_text'=>'Oh, maafkan saya.','order'=>39],
            ['start_time'=>107.160,'end_time'=>108.580,'target_text'=>'That was a sneeze.','source_text'=>'Itu adalah bersin.','order'=>40],
            ['start_time'=>108.680,'end_time'=>110.100,'target_text'=>'I just sneezed.','source_text'=>'Saya baru bersin.','order'=>41],
            ['start_time'=>110.200,'end_time'=>112.860,'target_text'=>'Anyway, I haven\'t eaten anything yet today.','source_text'=>'Anyway, saya belum makan apa-apa lagi hari ini.','order'=>42],
            ['start_time'=>112.960,'end_time'=>115.500,'target_text'=>'Have you guys eaten anything yet today?','source_text'=>'Adakah korang dah makan apa-apa hari ini?','order'=>43],
            ['start_time'=>115.600,'end_time'=>117.140,'target_text'=>'Have you eaten yet?','source_text'=>'Dah makan belum?','order'=>44],
            ['start_time'=>117.240,'end_time'=>118.980,'target_text'=>'Yes, I have eaten.','source_text'=>'Ya, saya sudah makan.','order'=>45],
            ['start_time'=>119.080,'end_time'=>121.820,'target_text'=>'No, I haven\'t eaten yet today.','source_text'=>'Tidak, saya belum makan hari ini.','order'=>46],
            ['start_time'=>121.920,'end_time'=>125.220,'target_text'=>'I\'m going to go make something to eat, so come with me.','source_text'=>'Saya nak pergi buat sesuatu untuk makan, jom ikut saya.','order'=>47],
            ['start_time'=>125.320,'end_time'=>126.140,'target_text'=>'Okay.','source_text'=>'Okay.','order'=>48],
            ['start_time'=>126.240,'end_time'=>127.420,'target_text'=>'3,000.','source_text'=>'3,000.','order'=>49],
            ['start_time'=>127.520,'end_time'=>132.820,'target_text'=>'That is the amount of words you need to understand up to 95%','source_text'=>'Itulah jumlah perkataan yang anda perlukan untuk memahami sehingga 95%','order'=>50],
            ['start_time'=>132.920,'end_time'=>135.220,'target_text'=>'of spoken English.','source_text'=>'daripada pertuturan Bahasa Inggeris.','order'=>51],
            ['start_time'=>135.320,'end_time'=>142.940,'target_text'=>'But, if you want to keep improving after that, I\'ve now added the next 2,000 most common English words, so you can build the','source_text'=>'Tapi, jika anda ingin terus meningkatkan diri, saya kini telah menambah 2,000 perkataan Bahasa Inggeris paling biasa berikutnya, supaya anda boleh membina','order'=>52],
            ['start_time'=>143.040,'end_time'=>147.780,'target_text'=>'full 5,000 word set and understand up to 98%','source_text'=>'set penuh 5,000 perkataan dan faham sehingga 98%','order'=>53],
            ['start_time'=>147.880,'end_time'=>149.900,'target_text'=>'of spoken English.','source_text'=>'daripada pertuturan Bahasa Inggeris.','order'=>54],
            ['start_time'=>150.000,'end_time'=>159.340,'target_text'=>'So, now you can start with the 3,000 word PDF, continue with the next 2,000 word PDF, or get both together as the full 5,000','source_text'=>'Jadi, sekarang anda boleh mulakan dengan PDF 3,000 perkataan, sambung dengan PDF 2,000 perkataan berikutnya, atau dapatkan kedua-duanya sebagai set lengkap 5,000','order'=>55],
            ['start_time'=>159.440,'end_time'=>165.780,'target_text'=>'most common English words PDF that will allow you to understand up to 98%','source_text'=>'perkataan Bahasa Inggeris paling biasa dalam PDF yang membolehkan anda faham sehingga 98%','order'=>56],
            ['start_time'=>165.880,'end_time'=>167.220,'target_text'=>'of spoken English.','source_text'=>'daripada pertuturan Bahasa Inggeris.','order'=>57],
            ['start_time'=>167.320,'end_time'=>174.340,'target_text'=>'And in these new versions, there are now images as well to help you learn even faster.','source_text'=>'Dan dalam versi baru ini, kini ada gambar juga untuk membantu anda belajar dengan lebih cepat.','order'=>58],
            ['start_time'=>174.440,'end_time'=>184.740,'target_text'=>'Each PDF includes clear definitions, real examples, and simple organization to help you stop studying random words and focus','source_text'=>'Setiap PDF mengandungi definisi yang jelas, contoh nyata, dan susunan yang mudah untuk membantu anda berhenti mengkaji perkataan rawak dan fokus','order'=>59],
            ['start_time'=>184.840,'end_time'=>188.100,'target_text'=>'on the vocabulary that actually matters.','source_text'=>'kepada kosa kata yang benar-benar penting.','order'=>60],
            ['start_time'=>188.200,'end_time'=>192.960,'target_text'=>'You can get them from the link in the description or at vulcaenglish.com.','source_text'=>'Anda boleh dapatkannya dari pautan dalam penerangan atau di vulcaenglish.com.','order'=>61],
            ['start_time'=>193.080,'end_time'=>193.980,'target_text'=>'Okay, guys.','source_text'=>'Okay, kawan-kawan.','order'=>62],
            ['start_time'=>194.080,'end_time'=>196.020,'target_text'=>'We are in the kitchen now.','source_text'=>'Kita sekarang berada di dapur.','order'=>63],
            ['start_time'=>196.120,'end_time'=>199.900,'target_text'=>'My fridge is right here to my right hand side.','source_text'=>'Peti sejuk saya ada di sebelah kanan saya.','order'=>64],
            ['start_time'=>200.000,'end_time'=>204.400,'target_text'=>'So, what am I doing right now?','source_text'=>'Jadi, apa yang saya lakukan sekarang?','order'=>65],
            ['start_time'=>207.600,'end_time'=>210.300,'target_text'=>'I\'m opening the fridge.','source_text'=>'Saya sedang membuka peti sejuk.','order'=>66],
            ['start_time'=>210.400,'end_time'=>212.180,'target_text'=>'This is the fridge door.','source_text'=>'Ini adalah pintu peti sejuk.','order'=>67],
            ['start_time'=>212.280,'end_time'=>218.220,'target_text'=>'There are a lot of shelves in the fridge, but what I need is some yogurt.','source_text'=>'Ada banyak rak dalam peti sejuk, tapi yang saya perlukan adalah yogurt.','order'=>68],
            ['start_time'=>218.320,'end_time'=>220.180,'target_text'=>'I will put that on the counter.','source_text'=>'Saya akan letak itu di atas kaunter.','order'=>69],
            ['start_time'=>220.280,'end_time'=>221.700,'target_text'=>'Also, I have a pot here.','source_text'=>'Juga, saya ada periuk di sini.','order'=>70],
            ['start_time'=>221.800,'end_time'=>223.900,'target_text'=>'I will take that out as well.','source_text'=>'Saya akan keluarkan itu juga.','order'=>71],
            ['start_time'=>224.000,'end_time'=>227.260,'target_text'=>'And uh some rice.','source_text'=>'Dan nasi.','order'=>72],
            ['start_time'=>227.360,'end_time'=>230.180,'target_text'=>'I did actually recently','source_text'=>'Saya baru-baru ini','order'=>73],
            ['start_time'=>230.280,'end_time'=>231.820,'target_text'=>'buy a rice cooker.','source_text'=>'beli periuk nasi.','order'=>74],
            ['start_time'=>231.920,'end_time'=>239.940,'target_text'=>'You can also say I purchased a rice cooker, but I just tend to say buy since it\'s a shorter word, it\'s easier to say, and','source_text'=>'Anda juga boleh kata saya \'purchased\' periuk nasi, tapi saya selalu guna \'buy\' kerana ia perkataan yang lebih pendek, lebih mudah diucapkan, dan','order'=>75],
            ['start_time'=>240.040,'end_time'=>241.180,'target_text'=>'it\'s just faster.','source_text'=>'lebih cepat.','order'=>76],
            ['start_time'=>241.280,'end_time'=>243.540,'target_text'=>'So, I bought a rice cooker today.','source_text'=>'Jadi, saya beli periuk nasi hari ini.','order'=>77],
            ['start_time'=>243.640,'end_time'=>252.020,'target_text'=>'It was like $16 because it\'s just easier to have rice like that and it\'ll keep the rice warm and like easy [music] to eat.','source_text'=>'Ia berharga lebih kurang $16 kerana lebih mudah ada nasi macam tu dan ia akan kekalkan nasi panas dan [muzik] senang dimakan.','order'=>78],
            ['start_time'=>252.120,'end_time'=>252.730,'target_text'=>'You can hear that?','source_text'=>'Anda dengar tu?','order'=>79],
            ['start_time'=>252.830,'end_time'=>256.460,'target_text'=>'[clears throat] It\'s ringing because I have left the fridge door open.','source_text'=>'[bersihkan tekak] Ia berbunyi kerana saya biarkan pintu peti sejuk terbuka.','order'=>80],
            ['start_time'=>256.560,'end_time'=>258.740,'target_text'=>'Let me just take out the kimchi.','source_text'=>'Biar saya keluarkan kimchi.','order'=>81],
            ['start_time'=>258.840,'end_time'=>260.340,'target_text'=>'I love kimchi.','source_text'=>'Saya suka kimchi.','order'=>82],
            ['start_time'=>260.440,'end_time'=>265.820,'target_text'=>'Do you guys love kimchi or do you like kimchi or do you hate kimchi?','source_text'=>'Adakah korang suka kimchi atau adakah korang benci kimchi?','order'=>83],
            ['start_time'=>265.920,'end_time'=>266.320,'target_text'=>'Let me know.','source_text'=>'Beritahu saya.','order'=>84],
            ['start_time'=>266.400,'end_time'=>269.980,'target_text'=>'Make a sentence describing how you feel about kimchi.','source_text'=>'Buat satu ayat yang menerangkan perasaan anda tentang kimchi.','order'=>85],
            ['start_time'=>270.080,'end_time'=>273.620,'target_text'=>'And if you haven\'t tried it, do you think you would like it or no?','source_text'=>'Dan kalau anda belum cuba, adakah anda rasa anda akan suka atau tidak?','order'=>86],
            ['start_time'=>273.720,'end_time'=>279.540,'target_text'=>'We also have some chicken and I\'m just checking the expiration date on this chicken.','source_text'=>'Kami juga ada ayam dan saya sedang menyemak tarikh luput ayam ini.','order'=>87],
            ['start_time'=>279.640,'end_time'=>281.100,'target_text'=>'Oh, it\'s halal certified.','source_text'=>'Oh, ia halal bersertifikat.','order'=>88],
            ['start_time'=>281.200,'end_time'=>284.780,'target_text'=>'I believe HSD means expiration date.','source_text'=>'Saya percaya HSD bermaksud tarikh luput.','order'=>89],
            ['start_time'=>284.880,'end_time'=>288.140,'target_text'=>'So, it was packaged on the 12th and expires on the 17th.','source_text'=>'Jadi, ia dibungkus pada tarikh 12 dan luput pada tarikh 17.','order'=>90],
            ['start_time'=>288.240,'end_time'=>291.020,'target_text'=>'That is tomorrow, so I will cook this chicken today.','source_text'=>'Itu esok, jadi saya akan masak ayam ini hari ini.','order'=>91],
            ['start_time'=>291.120,'end_time'=>293.500,'target_text'=>'I have two packets of chicken breast here.','source_text'=>'Saya ada dua paket dada ayam di sini.','order'=>92],
            ['start_time'=>293.600,'end_time'=>300.700,'target_text'=>'Both of these are in red packages and there is plastic covering the chicken here and it\'s in a plastic bag as well.','source_text'=>'Kedua-duanya dalam bungkusan merah dan ada plastik yang melindungi ayam dan ia juga dalam beg plastik.','order'=>93],
            ['start_time'=>300.800,'end_time'=>304.740,'target_text'=>'But, these are chicken breasts and they expire tomorrow.','source_text'=>'Tapi, ini adalah dada ayam dan ia luput esok.','order'=>94],
            ['start_time'=>304.840,'end_time'=>310.620,'target_text'=>'That means you can\'t eat it anymore after tomorrow because it\'s off and you can get sick.','source_text'=>'Bermaksud anda tidak boleh makan selepas esok kerana ia sudah basi dan anda boleh sakit.','order'=>95],
            ['start_time'=>310.720,'end_time'=>313.300,'target_text'=>'So, I will cook these today and it will last longer.','source_text'=>'Jadi, saya akan masak ini hari ini dan ia akan tahan lebih lama.','order'=>96],
            ['start_time'=>313.400,'end_time'=>316.380,'target_text'=>'Also, I have some baby carrots.','source_text'=>'Juga, saya ada beberapa lobak merah kecil.','order'=>97],
            ['start_time'=>316.480,'end_time'=>319.820,'target_text'=>'I\'ll probably just munch on these like normally.','source_text'=>'Saya mungkin akan makan ini macam biasa sahaja.','order'=>98],
            ['start_time'=>319.920,'end_time'=>322.020,'target_text'=>'Like a rabbit or something.','source_text'=>'Macam arnab atau sesuatu.','order'=>99],
            ['start_time'=>322.120,'end_time'=>329.980,'target_text'=>'And I have Ooh, I think I should buy cucumbers low-key, but I have all this bok choy that I need to eat.','source_text'=>'Dan saya ada — Oh, saya rasa saya patut beli timun, tapi saya ada semua bok choy yang perlu saya makan.','order'=>100],
            ['start_time'=>330.080,'end_time'=>333.540,'target_text'=>'And all of this spinach.','source_text'=>'Dan semua bayam ini.','order'=>101],
            ['start_time'=>333.640,'end_time'=>335.500,'target_text'=>'Yeah, all of this spinach as well.','source_text'=>'Ya, semua bayam ini juga.','order'=>102],
            ['start_time'=>335.600,'end_time'=>337.960,'target_text'=>'Organic spinach.','source_text'=>'Bayam organik.','order'=>103],
            ['start_time'=>339.440,'end_time'=>341.620,'target_text'=>'So, I need to eat those things.','source_text'=>'Jadi, saya perlu makan benda-benda itu.','order'=>104],
            ['start_time'=>341.720,'end_time'=>343.700,'target_text'=>'Let me show you inside my fridge.','source_text'=>'Biar saya tunjukkan bahagian dalam peti sejuk saya.','order'=>105],
            ['start_time'=>343.800,'end_time'=>345.500,'target_text'=>'So, this is the inside of my fridge.','source_text'=>'Jadi, ini adalah bahagian dalam peti sejuk saya.','order'=>106],
            ['start_time'=>345.600,'end_time'=>347.620,'target_text'=>'You can see it\'s pretty empty.','source_text'=>'Anda boleh lihat ia agak kosong.','order'=>107],
            ['start_time'=>347.720,'end_time'=>351.500,'target_text'=>'I just have the chicken, some Coke Zero, and another yogurt.','source_text'=>'Saya hanya ada ayam, beberapa Coke Zero, dan lagi satu yogurt.','order'=>108],
            ['start_time'=>351.600,'end_time'=>354.980,'target_text'=>'So, I will be eating this soon.','source_text'=>'Jadi, saya akan makan ini tidak lama lagi.','order'=>109],
            ['start_time'=>355.080,'end_time'=>356.540,'target_text'=>'That\'s a fresh pack of yogurt.','source_text'=>'Itu adalah paket yogurt yang baru.','order'=>110],
            ['start_time'=>356.640,'end_time'=>359.660,'target_text'=>'And then up top here, I have frozen berries.','source_text'=>'Dan di bahagian atas sini, saya ada beri beku.','order'=>111],
            ['start_time'=>359.760,'end_time'=>368.080,'target_text'=>'And I also bought a blender so that I can make smoothies with these frozen berries.','source_text'=>'Dan saya juga beli pengisar supaya saya boleh buat smoothie dengan beri beku ini.','order'=>112],
            ['start_time'=>368.480,'end_time'=>370.860,'target_text'=>'But yeah, the top part here is the freezer.','source_text'=>'Tapi ya, bahagian atas ini adalah peti ais.','order'=>113],
            ['start_time'=>370.960,'end_time'=>375.300,'target_text'=>'Now, I\'m going to close the freezer door.','source_text'=>'Sekarang, saya nak tutup pintu peti ais.','order'=>114],
            ['start_time'=>375.400,'end_time'=>376.820,'target_text'=>'So, this is my kitchen.','source_text'=>'Jadi, ini adalah dapur saya.','order'=>115],
            ['start_time'=>376.920,'end_time'=>381.700,'target_text'=>'This right here, you can call the counter or the counter top.','source_text'=>'Ini di sini boleh dipanggil kaunter atau permukaan dapur.','order'=>116],
            ['start_time'=>381.800,'end_time'=>382.500,'target_text'=>'Either one.','source_text'=>'Mana-mana pun boleh.','order'=>117],
            ['start_time'=>382.600,'end_time'=>384.660,'target_text'=>'This is my electric stove.','source_text'=>'Ini adalah dapur elektrik saya.','order'=>118],
            ['start_time'=>384.760,'end_time'=>386.940,'target_text'=>'You can see I can turn it on with that button.','source_text'=>'Anda boleh lihat saya boleh hidupkannya dengan butang itu.','order'=>119],
            ['start_time'=>387.040,'end_time'=>389.180,'target_text'=>'And I can turn it off with the same button.','source_text'=>'Dan saya boleh padamkannya dengan butang yang sama.','order'=>120],
            ['start_time'=>389.280,'end_time'=>393.580,'target_text'=>'The things I took out were this yogurt, this pot.','source_text'=>'Benda yang saya keluarkan adalah yogurt ini, periuk ini.','order'=>121],
            ['start_time'=>393.680,'end_time'=>396.580,'target_text'=>'This has chicken in it, so I will warm that up.','source_text'=>'Ini ada ayam di dalamnya, jadi saya akan panaskannya.','order'=>122],
            ['start_time'=>396.680,'end_time'=>398.740,'target_text'=>'And also this pot with rice.','source_text'=>'Dan juga periuk nasi ini.','order'=>123],
            ['start_time'=>398.840,'end_time'=>400.660,'target_text'=>'I will warm this up as well.','source_text'=>'Saya akan panas ini juga.','order'=>124],
            ['start_time'=>400.760,'end_time'=>406.220,'target_text'=>'And then I took out some kimchi so I can have the kimchi with my rice and chicken.','source_text'=>'Dan kemudian saya keluarkan kimchi supaya saya boleh makan kimchi dengan nasi dan ayam.','order'=>125],
            ['start_time'=>406.320,'end_time'=>408.300,'target_text'=>'There is also bok choy in here.','source_text'=>'Ada juga bok choy dalam sini.','order'=>126],
            ['start_time'=>408.400,'end_time'=>410.700,'target_text'=>'I know I put it in a pot in the fridge.','source_text'=>'Saya tahu saya letak dalam periuk dalam peti sejuk.','order'=>127],
            ['start_time'=>410.800,'end_time'=>412.580,'target_text'=>'It should be in a plastic container.','source_text'=>'Ia sepatutnya dalam bekas plastik.','order'=>128],
            ['start_time'=>412.680,'end_time'=>418.380,'target_text'=>'I just don\'t have any plastic containers, and I don\'t have many pots, so I just put it together there.','source_text'=>'Saya hanya tak ada bekas plastik, dan saya tak banyak periuk, jadi saya letak sahaja semua sekali.','order'=>129],
            ['start_time'=>418.480,'end_time'=>424.100,'target_text'=>'But I ordered some plastic containers so that I can put my food in there if I don\'t eat it all.','source_text'=>'Tapi saya dah order beberapa bekas plastik supaya saya boleh letak makanan dalam tu kalau tidak habis makan.','order'=>130],
            ['start_time'=>424.200,'end_time'=>429.540,'target_text'=>'And I just took out these carrots as well cuz I think I\'ll just eat these as a snack.','source_text'=>'Dan saya baru keluarkan lobak merah ini juga kerana saya rasa saya akan makan ini sebagai snek.','order'=>131],
            ['start_time'=>429.640,'end_time'=>433.340,'target_text'=>'So, I bought this loaf of bread like a couple days ago.','source_text'=>'Jadi, saya beli sebuku roti ini beberapa hari lepas.','order'=>132],
            ['start_time'=>433.440,'end_time'=>435.180,'target_text'=>'But you can hear it.','source_text'=>'Tapi anda boleh dengar.','order'=>133],
            ['start_time'=>435.280,'end_time'=>437.340,'target_text'=>'It\'s rock hard.','source_text'=>'Ia keras macam batu.','order'=>134],
            ['start_time'=>437.440,'end_time'=>440.120,'target_text'=>'It\'s like like','source_text'=>'Ia seperti seperti','order'=>135],
            ['start_time'=>440.280,'end_time'=>441.380,'target_text'=>'It\'s rock hard.','source_text'=>'Ia keras macam batu.','order'=>136],
            ['start_time'=>441.480,'end_time'=>443.180,'target_text'=>'So, I don\'t think I can eat this.','source_text'=>'Jadi, saya rasa saya tidak boleh makan ini.','order'=>137],
            ['start_time'=>443.280,'end_time'=>449.980,'target_text'=>'But I still have the whole loaf, so I think I\'ll freeze it and then I\'ll warm it up in the microwave to make it softer when','source_text'=>'Tapi saya masih ada seloyang penuh, jadi saya rasa saya akan beku dan kemudian panas dalam gelombang mikro untuk buatkan lebih lembut bila','order'=>138],
            ['start_time'=>450.080,'end_time'=>451.580,'target_text'=>'I want to eat it.','source_text'=>'saya nak makan.','order'=>139],
            ['start_time'=>451.680,'end_time'=>456.420,'target_text'=>'So, now you can see I have my two pots on the stove.','source_text'=>'Jadi, sekarang anda boleh lihat saya ada dua periuk di atas dapur.','order'=>140],
            ['start_time'=>456.520,'end_time'=>460.500,'target_text'=>'What is this part of the pot called?','source_text'=>'Apa nama bahagian periuk ini?','order'=>141],
            ['start_time'=>460.600,'end_time'=>462.180,'target_text'=>'This is called the handle.','source_text'=>'Ini dipanggil pemegang (handle).','order'=>142],
            ['start_time'=>462.280,'end_time'=>465.240,'target_text'=>'And what am I doing right now?','source_text'=>'Dan apa yang saya lakukan sekarang?','order'=>143],
            ['start_time'=>466.280,'end_time'=>470.260,'target_text'=>'I\'m lifting up the pot by the handle.','source_text'=>'Saya sedang mengangkat periuk dengan pemegangannya.','order'=>144],
            ['start_time'=>470.360,'end_time'=>471.260,'target_text'=>'This is the lid.','source_text'=>'Ini adalah penutup periuk.','order'=>145],
            ['start_time'=>471.360,'end_time'=>474.420,'target_text'=>'The lid also has a handle, and I\'m taking the lid off.','source_text'=>'Penutup periuk juga ada pemegang, dan saya sedang membuka penutupnya.','order'=>146],
            ['start_time'=>474.520,'end_time'=>475.940,'target_text'=>'I\'m looking inside.','source_text'=>'Saya sedang melihat ke dalam.','order'=>147],
            ['start_time'=>476.040,'end_time'=>478.980,'target_text'=>'I think I will add a little bit of water.','source_text'=>'Saya rasa saya akan tambah sedikit air.','order'=>148],
            ['start_time'=>479.080,'end_time'=>486.700,'target_text'=>'I will add a little bit of water to this pot so I can just steam the vegetable and warm up the chicken at the same time.','source_text'=>'Saya akan tambah sedikit air ke dalam periuk ini supaya saya boleh kukus sayur dan panaskan ayam pada masa yang sama.','order'=>149],
            ['start_time'=>486.800,'end_time'=>487.980,'target_text'=>'And now I will turn it on.','source_text'=>'Dan sekarang saya akan hidupkan.','order'=>150],
            ['start_time'=>488.080,'end_time'=>493.200,'target_text'=>'There\'s a button here that I will press, and then I will turn the heat up.','source_text'=>'Ada butang di sini yang akan saya tekan, kemudian saya akan naikkan haba.','order'=>151],
            ['start_time'=>494.240,'end_time'=>499.320,'target_text'=>'So now that pot\'s going, and now I will also warm up the rice.','source_text'=>'Jadi sekarang periuk tu dah jalan, dan sekarang saya juga akan panaskan nasi.','order'=>152],
            ['start_time'=>500.480,'end_time'=>501.260,'target_text'=>'So I\'ll do the same thing.','source_text'=>'Jadi saya akan buat perkara yang sama.','order'=>153],
            ['start_time'=>501.360,'end_time'=>505.140,'target_text'=>'I\'ll turn it on, select the setting,','source_text'=>'Saya akan hidupkan, pilih tetapan,','order'=>154],
            ['start_time'=>505.240,'end_time'=>511.920,'target_text'=>'turn it up, and pour a little bit of water in there so that it steams nicely.','source_text'=>'naikkan haba, dan tuang sedikit air supaya ia berkukus dengan baik.','order'=>155],
            ['start_time'=>514.360,'end_time'=>518.220,'target_text'=>'Now I just put the lid on, and I\'ll just let it warm up.','source_text'=>'Sekarang saya letak penutupnya, dan saya biarkan ia panas.','order'=>156],
            ['start_time'=>518.320,'end_time'=>521.740,'target_text'=>'Okay, so we have the stuff cooking nicely.','source_text'=>'Okay, jadi benda-benda itu sedang dimasak dengan baik.','order'=>157],
            ['start_time'=>521.840,'end_time'=>524.340,'target_text'=>'You can see some steam coming from there.','source_text'=>'Anda boleh nampak ada wap keluar dari sana.','order'=>158],
            ['start_time'=>524.440,'end_time'=>526.020,'target_text'=>'The rice as well is warming up.','source_text'=>'Nasi juga sedang dipanaskan.','order'=>159],
            ['start_time'=>526.120,'end_time'=>527.860,'target_text'=>'I have it at 60°.','source_text'=>'Saya set ia pada 60°.','order'=>160],
            ['start_time'=>527.960,'end_time'=>536.980,'target_text'=>'This one is at 80°, and now I have a white plate here, and I\'m going to get two kiwis, one, two, and I\'m going to peel these','source_text'=>'Yang ini pada 80°, dan sekarang saya ada pinggan putih di sini, dan saya nak ambil dua biji kiwi, satu, dua, dan saya nak kupas kiwi-kiwi','order'=>161],
            ['start_time'=>537.080,'end_time'=>540.220,'target_text'=>'kiwis, and I\'m going to have them cuz I like kiwis.','source_text'=>'ini, dan saya nak makan kerana saya suka kiwi.','order'=>162],
            ['start_time'=>540.320,'end_time'=>545.380,'target_text'=>'And I\'m going to close this container, and I\'ll have the last one later tonight.','source_text'=>'Dan saya nak tutup bekas ini, dan saya akan makan yang terakhir nanti malam.','order'=>163],
            ['start_time'=>545.480,'end_time'=>549.900,'target_text'=>'These right here are potatoes, and that is a big bag of rice.','source_text'=>'Ini di sini adalah ubi kentang, dan itu adalah beg beras yang besar.','order'=>164],
            ['start_time'=>550.000,'end_time'=>553.980,'target_text'=>'So now I\'m going to >> [sighs] >> peel these uh kiwis.','source_text'=>'Jadi sekarang saya nak >> [mengeluh] >> kupas kiwi-kiwi ini.','order'=>165],
            ['start_time'=>554.080,'end_time'=>556.660,'target_text'=>'I\'m actually not really sure how to peel kiwis.','source_text'=>'Saya sebenarnya tidak tahu macam mana nak kupas kiwi.','order'=>166],
            ['start_time'=>556.760,'end_time'=>558.300,'target_text'=>'I always just like open them.','source_text'=>'Saya selalu buka begini sahaja.','order'=>167],
            ['start_time'=>558.400,'end_time'=>565.680,'target_text'=>'I see some people like peel them really nice, but I always just open them and then take the inside with a spoon like this.','source_text'=>'Saya nampak ada orang yang kupas dengan cantik, tapi saya selalu buka dan ambil bahagian dalam dengan sudu macam ini.','order'=>168],
            ['start_time'=>566.320,'end_time'=>570.040,'target_text'=>'Like this, and then just eat it.','source_text'=>'Macam ini, kemudian makan sahaja.','order'=>169],
            ['start_time'=>571.240,'end_time'=>572.820,'target_text'=>'Mhm.','source_text'=>'Mhm.','order'=>170],
            ['start_time'=>572.920,'end_time'=>574.540,'target_text'=>'It created minimal mess.','source_text'=>'Ia buat sedikit sahaja kotoran.','order'=>171],
            ['start_time'=>574.640,'end_time'=>577.360,'target_text'=>'I only spilled a little bit.','source_text'=>'Saya tumpah sikit sahaja.','order'=>172],
            ['start_time'=>577.680,'end_time'=>579.260,'target_text'=>'Mhm, but it tastes fire.','source_text'=>'Mhm, tapi ia sedap.','order'=>173],
            ['start_time'=>579.360,'end_time'=>580.620,'target_text'=>'I think it\'s a spoon.','source_text'=>'Saya rasa ini pasal sudu.','order'=>174],
            ['start_time'=>580.720,'end_time'=>581.900,'target_text'=>'We\'ll blame it on the spoon.','source_text'=>'Kita salahkan sudu.','order'=>175],
            ['start_time'=>582.000,'end_time'=>583.300,'target_text'=>'The spoon is too big.','source_text'=>'Sudunya terlalu besar.','order'=>176],
            ['start_time'=>583.400,'end_time'=>585.020,'target_text'=>'But besides that, it is really good.','source_text'=>'Tapi selain itu, ia sangat sedap.','order'=>177],
            ['start_time'=>585.120,'end_time'=>587.940,'target_text'=>'And I don\'t know, I don\'t think you\'re supposed to eat the skin.','source_text'=>'Dan saya tak tahu, saya rasa kulitnya tidak perlu dimakan.','order'=>178],
            ['start_time'=>588.040,'end_time'=>589.620,'target_text'=>'I don\'t really have kiwis that often.','source_text'=>'Saya jarang makan kiwi.','order'=>179],
            ['start_time'=>589.720,'end_time'=>594.340,'target_text'=>'It\'s been like years, I feel like since I\'ve had a kiwi.','source_text'=>'Rasa macam dah bertahun-tahun, saya rasa, sejak saya makan kiwi.','order'=>180],
            ['start_time'=>594.440,'end_time'=>597.220,'target_text'=>'But they\'re really good.','source_text'=>'Tapi ia sangat sedap.','order'=>181],
            ['start_time'=>597.320,'end_time'=>599.060,'target_text'=>'This kiwi is very juicy.','source_text'=>'Kiwi ini sangat berair.','order'=>182],
            ['start_time'=>599.160,'end_time'=>600.300,'target_text'=>'Not very sweet, actually.','source_text'=>'Sebenarnya tidak terlalu manis.','order'=>183],
            ['start_time'=>600.400,'end_time'=>601.540,'target_text'=>'It\'s not very sweet.','source_text'=>'Ia tidak terlalu manis.','order'=>184],
            ['start_time'=>601.640,'end_time'=>604.460,'target_text'=>'It\'s sweet, but it\'s not overwhelmingly sweet.','source_text'=>'Ia manis, tapi tidak terlalu manis.','order'=>185],
            ['start_time'=>604.560,'end_time'=>608.620,'target_text'=>'It\'s a nice nice flavor, and it\'s not too bad overall.','source_text'=>'Ia rasa yang bagus, dan tidak terlalu teruk secara keseluruhannya.','order'=>186],
            ['start_time'=>608.720,'end_time'=>612.940,'target_text'=>'I\'ve seen some kiwis that are like very very like vibrant green.','source_text'=>'Saya pernah nampak ada kiwi yang sangat-sangat hijau terang.','order'=>187],
            ['start_time'=>613.040,'end_time'=>614.780,'target_text'=>'This one isn\'t very green.','source_text'=>'Yang ini tidak terlalu hijau.','order'=>188],
            ['start_time'=>614.880,'end_time'=>617.620,'target_text'=>'It\'s more like a like a faded faded green color.','source_text'=>'Ia lebih kepada warna hijau pudar.','order'=>189],
            ['start_time'=>617.720,'end_time'=>620.780,'target_text'=>'It\'s not that saturated.','source_text'=>'Tidak terlalu tepu warnanya.','order'=>190],
            ['start_time'=>620.880,'end_time'=>622.060,'target_text'=>'Mhm.','source_text'=>'Mhm.','order'=>191],
            ['start_time'=>622.160,'end_time'=>624.540,'target_text'=>'Let me plate that food and bring it here.','source_text'=>'Biar saya hidangkan makanan itu dan bawa ke sini.','order'=>192],
            ['start_time'=>624.640,'end_time'=>625.820,'target_text'=>'So, this is the food.','source_text'=>'Jadi, ini adalah makanannya.','order'=>193],
            ['start_time'=>625.920,'end_time'=>632.260,'target_text'=>'I know it doesn\'t really look visually pleasing, but I promise you a couple days ago it looked a lot better.','source_text'=>'Saya tahu ia tidak kelihatan cantik, tapi saya janji beberapa hari lepas ia kelihatan jauh lebih baik.','order'=>194],
            ['start_time'=>632.360,'end_time'=>635.220,'target_text'=>'I have bok choy, chicken, rice, and kimchi.','source_text'=>'Saya ada bok choy, ayam, nasi, dan kimchi.','order'=>195],
            ['start_time'=>635.320,'end_time'=>636.980,'target_text'=>'And this is the kimchi I have.','source_text'=>'Dan ini adalah kimchi yang saya ada.','order'=>196],
            ['start_time'=>637.080,'end_time'=>638.220,'target_text'=>'I love kimchi.','source_text'=>'Saya suka kimchi.','order'=>197],
            ['start_time'=>638.320,'end_time'=>643.460,'target_text'=>'Super good, very flavorful, and adds like that taste I like.','source_text'=>'Sangat sedap, sangat berperisa, dan menambahkan rasa yang saya suka.','order'=>198],
            ['start_time'=>643.560,'end_time'=>645.220,'target_text'=>'But yeah, this is the food I\'ll be eating.','source_text'=>'Tapi ya, ini makanan yang akan saya makan.','order'=>199],
            ['start_time'=>645.320,'end_time'=>647.060,'target_text'=>'This is my lunch.','source_text'=>'Ini adalah makan tengahari saya.','order'=>200],
            ['start_time'=>647.160,'end_time'=>648.060,'target_text'=>'It\'s about 12:00 p.m.','source_text'=>'Sekarang lebih kurang pukul 12 tengahari.','order'=>201],
            ['start_time'=>648.160,'end_time'=>648.560,'target_text'=>'now.','source_text'=>'sekarang.','order'=>202],
            ['start_time'=>648.560,'end_time'=>652.380,'target_text'=>'Let me know, guys, what are you having for lunch?','source_text'=>'Beritahu saya, kawan-kawan, apa yang korang makan tengahari?','order'=>203],
            ['start_time'=>652.480,'end_time'=>655.100,'target_text'=>'Or what did you have for lunch today?','source_text'=>'Atau apa yang korang makan tengahari hari ini?','order'=>204],
            ['start_time'=>655.200,'end_time'=>657.920,'target_text'=>'Let me know in the comments.','source_text'=>'Beritahu saya dalam komen.','order'=>205],
            ['start_time'=>659.920,'end_time'=>662.460,'target_text'=>'I just scooted my chair forward.','source_text'=>'Saya baru tolak kerusi saya ke depan.','order'=>206],
            ['start_time'=>662.560,'end_time'=>666.340,'target_text'=>'Or you can say I brought my chair forward.','source_text'=>'Atau anda boleh kata saya bawa kerusi saya ke depan.','order'=>207],
            ['start_time'=>666.440,'end_time'=>672.740,'target_text'=>'Now, I have a fork here in my right hand, and I\'m going to try a piece of the chicken with kimchi.','source_text'=>'Sekarang, saya ada garpu di tangan kanan saya, dan saya nak cuba sekeping ayam dengan kimchi.','order'=>208],
            ['start_time'=>672.840,'end_time'=>675.020,'target_text'=>'Chicken and kimchi.','source_text'=>'Ayam dan kimchi.','order'=>209],
            ['start_time'=>675.120,'end_time'=>676.100,'target_text'=>'Mhm.','source_text'=>'Mhm.','order'=>210],
            ['start_time'=>676.200,'end_time'=>676.560,'target_text'=>'Mhm.','source_text'=>'Mhm.','order'=>211],
            ['start_time'=>676.560,'end_time'=>676.960,'target_text'=>'Mhm.','source_text'=>'Mhm.','order'=>212],
            ['start_time'=>677.000,'end_time'=>677.700,'target_text'=>'Mhm.','source_text'=>'Mhm.','order'=>213],
            ['start_time'=>677.800,'end_time'=>678.460,'target_text'=>'Very good.','source_text'=>'Sangat sedap.','order'=>214],
            ['start_time'=>678.560,'end_time'=>680.880,'target_text'=>'I\'m a great chef.','source_text'=>'Saya adalah chef yang hebat.','order'=>215],
            ['start_time'=>681.880,'end_time'=>687.740,'target_text'=>'Anyway, I\'ll see you guys after when I clean up and make the yogurt bowl.','source_text'=>'Anyway, jumpa korang nanti bila saya dah kemas dan buat mangkuk yogurt.','order'=>216],
            ['start_time'=>687.840,'end_time'=>689.900,'target_text'=>'Okay, so I just finished eating.','source_text'=>'Okay, jadi saya baru selesai makan.','order'=>217],
            ['start_time'=>690.000,'end_time'=>691.900,'target_text'=>'I\'ll push my chair back in now.','source_text'=>'Saya akan tolak kerusi ke belakang sekarang.','order'=>218],
            ['start_time'=>692.000,'end_time'=>695.260,'target_text'=>'Here you can see I almost ate everything except for the last of the bok choy.','source_text'=>'Di sini anda boleh lihat saya hampir habis makan kecuali bok choy yang terakhir.','order'=>219],
            ['start_time'=>695.360,'end_time'=>698.580,'target_text'=>'Low-key was a lot, so I couldn\'t really finish it.','source_text'=>'Rasa macam banyak sangat, jadi saya tak dapat habiskan.','order'=>220],
            ['start_time'=>698.680,'end_time'=>703.420,'target_text'=>'And then I had the other kiwi in this plate, and I ate a lot more kimchi.','source_text'=>'Dan kemudian saya ada kiwi satu lagi dalam pinggan ni, dan saya makan banyak lagi kimchi.','order'=>221],
            ['start_time'=>703.520,'end_time'=>706.220,'target_text'=>'I think I\'ll eat like two of these a week.','source_text'=>'Saya rasa saya akan makan dua biji seminggu.','order'=>222],
            ['start_time'=>706.320,'end_time'=>707.260,'target_text'=>'It\'s a kilo each.','source_text'=>'Satu kilo setiap satu.','order'=>223],
            ['start_time'=>707.360,'end_time'=>708.580,'target_text'=>'>> You should buy a bigger one then.','source_text'=>'Anda patut beli yang lebih besar kalau macam tu.','order'=>224],
            ['start_time'=>708.680,'end_time'=>711.260,'target_text'=>'If [snorts] you\'re going to eat that much, it\'s better to buy in bulk.','source_text'=>'Kalau anda nak makan sebanyak itu, lebih baik beli dalam kuantiti banyak.','order'=>225],
            ['start_time'=>711.360,'end_time'=>712.500,'target_text'=>'>> But I didn\'t see in bulk though.','source_text'=>'Tapi saya tak nampak yang dijual secara pukal pun.','order'=>226],
            ['start_time'=>712.600,'end_time'=>714.380,'target_text'=>'I This was the biggest size I saw.','source_text'=>'Ini adalah saiz terbesar yang saya jumpa.','order'=>227],
            ['start_time'=>714.480,'end_time'=>720.380,'target_text'=>'>> If you go to a dedicated Korean market, which they have a lot of in this neighborhood, you\'ll definitely be able to find','source_text'=>'Kalau pergi ke kedai Korea yang khusus, yang banyak ada dalam kawasan ni, anda pasti boleh jumpa','order'=>228],
            ['start_time'=>720.480,'end_time'=>722.020,'target_text'=>'someone selling them in bulk.','source_text'=>'seseorang yang jual secara pukal.','order'=>229],
            ['start_time'=>722.120,'end_time'=>722.700,'target_text'=>'>> Mhm.','source_text'=>'Mhm.','order'=>230],
            ['start_time'=>722.800,'end_time'=>725.980,'target_text'=>'Yeah, cuz low-key I do eat a lot of kimchi.','source_text'=>'Ya, sebab saya memang banyak makan kimchi.','order'=>231],
            ['start_time'=>726.080,'end_time'=>728.980,'target_text'=>'Before, like my first time in Korea, I didn\'t like kimchi.','source_text'=>'Dulu, masa pertama kali saya ke Korea, saya tak suka kimchi.','order'=>232],
            ['start_time'=>729.080,'end_time'=>731.980,'target_text'=>'I was like, I never really ate it when they gave it at restaurants and I didn\'t like it.','source_text'=>'Saya macam, saya tak pernah makan bila restoran hidangkan dan saya tak suka.','order'=>233],
            ['start_time'=>732.080,'end_time'=>735.820,'target_text'=>'That was for my first semester I studied in Korea for 4 months.','source_text'=>'Itu masa semester pertama saya belajar di Korea selama 4 bulan.','order'=>234],
            ['start_time'=>735.920,'end_time'=>742.140,'target_text'=>'And then there was like a 2-month break, and I came back for my second semester, and I was craving kimchi.','source_text'=>'Kemudian ada rehat 2 bulan, saya balik untuk semester kedua, dan saya teringinkan kimchi.','order'=>235],
            ['start_time'=>742.240,'end_time'=>743.220,'target_text'=>'And I was just eating it, dude.','source_text'=>'Dan saya makan sahaja, kawan.','order'=>236],
            ['start_time'=>743.320,'end_time'=>743.980,'target_text'=>'I love kimchi.','source_text'=>'Saya suka kimchi.','order'=>237],
            ['start_time'=>744.080,'end_time'=>747.100,'target_text'=>'I can just eat kimchi with rice now.','source_text'=>'Saya boleh makan kimchi dengan nasi sahaja sekarang.','order'=>238],
            ['start_time'=>747.200,'end_time'=>748.260,'target_text'=>'I like kimchi a lot.','source_text'=>'Saya suka kimchi sangat.','order'=>239],
            ['start_time'=>748.360,'end_time'=>748.820,'target_text'=>'It\'s really good.','source_text'=>'Ia sangat sedap.','order'=>240],
            ['start_time'=>748.920,'end_time'=>751.500,'target_text'=>'But anyway, I\'m going to start cleaning up here.','source_text'=>'Tapi anyway, saya nak mula mengemas di sini.','order'=>241],
            ['start_time'=>751.600,'end_time'=>753.420,'target_text'=>'I have to wash these dishes.','source_text'=>'Saya kena basuh pinggan-pinggan ini.','order'=>242],
            ['start_time'=>753.520,'end_time'=>757.780,'target_text'=>'There are some dishes in the sink, some on the counter, and some on the stove.','source_text'=>'Ada beberapa pinggan dalam sinki, beberapa di kaunter, dan beberapa di atas dapur.','order'=>243],
            ['start_time'=>757.880,'end_time'=>760.420,'target_text'=>'So, I have to wash these, and then I\'ll have some carrots after.','source_text'=>'Jadi, saya kena basuh semua ini, kemudian saya akan makan lobak merah selepas.','order'=>244],
            ['start_time'=>760.520,'end_time'=>762.140,'target_text'=>'Wash this glass as well.','source_text'=>'Basuh gelas ini juga.','order'=>245],
            ['start_time'=>762.240,'end_time'=>765.420,'target_text'=>'Now, I\'m going to clean up this kitchen area.','source_text'=>'Sekarang, saya nak kemas kawasan dapur ini.','order'=>246],
            ['start_time'=>765.520,'end_time'=>766.580,'target_text'=>'I\'m going to clean it all up.','source_text'=>'Saya nak kemas semuanya.','order'=>247],
            ['start_time'=>766.680,'end_time'=>769.220,'target_text'=>'After I clean it, we\'ll have a shadowing.','source_text'=>'Selepas saya kemas, kita akan buat latihan bayangan.','order'=>248],
            ['start_time'=>769.320,'end_time'=>776.060,'target_text'=>'Actually, let\'s have a shadowing and accent training practice right now to practice your pronunciation and your accent.','source_text'=>'Sebenarnya, jom kita buat latihan bayangan dan latihan sebutan sekarang untuk melatih sebutan dan loghat anda.','order'=>249],
            ['start_time'=>776.160,'end_time'=>777.660,'target_text'=>'So, this will be the scene.','source_text'=>'Jadi, ini akan jadi pemandangannya.','order'=>250],
            ['start_time'=>777.760,'end_time'=>782.140,'target_text'=>'Take a good look at it, and now we\'ll start describing it.','source_text'=>'Tengok baik-baik, dan sekarang kita akan mula menerangkannya.','order'=>251],
            ['start_time'=>782.240,'end_time'=>784.500,'target_text'=>'This is a modern kitchen.','source_text'=>'Ini adalah dapur moden.','order'=>252],
            ['start_time'=>784.600,'end_time'=>787.860,'target_text'=>'The kitchen looks clean, bright, and simple.','source_text'=>'Dapur ini kelihatan bersih, terang, dan mudah.','order'=>253],
            ['start_time'=>787.960,'end_time'=>795.180,'target_text'=>'The cabinets are light brown with a wood pattern, and the countertops are black and shiny.','source_text'=>'Almari-almari itu berwarna coklat muda dengan corak kayu, dan permukaan dapur berwarna hitam dan berkilat.','order'=>254],
            ['start_time'=>795.280,'end_time'=>803.820,'target_text'=>'There are many objects on the counter, including plates, pots, vegetables, bananas, and a bottle of oil.','source_text'=>'Ada banyak benda di atas kaunter, termasuk pinggan, periuk, sayur-sayuran, pisang, dan sebotol minyak.','order'=>255],
            ['start_time'=>803.920,'end_time'=>806.460,'target_text'=>'The kitchen has a sink on the left side.','source_text'=>'Dapur ini ada sinki di sebelah kiri.','order'=>256],
            ['start_time'=>806.560,'end_time'=>810.740,'target_text'=>'Above the sink, there is a gray towel hanging near the faucet.','source_text'=>'Di atas sinki, ada tuala kelabu yang tergantung berhampiran paip.','order'=>257],
            ['start_time'=>810.840,'end_time'=>815.580,'target_text'=>'Next to the sink, there are some dishes and food on white plates.','source_text'=>'Di sebelah sinki, ada beberapa pinggan dan makanan di atas pinggan putih.','order'=>258],
            ['start_time'=>815.680,'end_time'=>820.940,'target_text'=>'In the middle of the kitchen, there is a black stove with two pots on top of it.','source_text'=>'Di tengah-tengah dapur, ada dapur hitam dengan dua periuk di atasnya.','order'=>259],
            ['start_time'=>821.040,'end_time'=>824.460,'target_text'=>'One pot is silver and the other pot is black.','source_text'=>'Satu periuk berwarna perak dan periuk satu lagi berwarna hitam.','order'=>260],
            ['start_time'=>824.560,'end_time'=>827.300,'target_text'=>'The stove is built into the counter.','source_text'=>'Dapur itu dibina dalam kaunter.','order'=>261],
            ['start_time'=>827.400,'end_time'=>830.660,'target_text'=>'Above the stove, there is a silver range hood.','source_text'=>'Di atas dapur, ada tudung dapur berwarna perak.','order'=>262],
            ['start_time'=>830.760,'end_time'=>835.260,'target_text'=>'The range hood helps remove smoke and smells while cooking.','source_text'=>'Tudung dapur membantu membuang asap dan bau semasa memasak.','order'=>263],
            ['start_time'=>835.360,'end_time'=>839.900,'target_text'=>'There are also wooden cabinets above and below the counter.','source_text'=>'Ada juga almari kayu di atas dan di bawah kaunter.','order'=>264],
            ['start_time'=>840.000,'end_time'=>845.140,'target_text'=>'Some cabinets are open and you can see small objects inside them.','source_text'=>'Sesetengah almari terbuka dan anda boleh nampak benda-benda kecil di dalamnya.','order'=>265],
            ['start_time'=>845.240,'end_time'=>851.580,'target_text'=>'On the right side of the counter, there are bananas and a plastic container with vegetables.','source_text'=>'Di sebelah kanan kaunter, ada pisang dan bekas plastik berisi sayur-sayuran.','order'=>266],
            ['start_time'=>851.680,'end_time'=>855.860,'target_text'=>'There is also a plate with food and a fork on it.','source_text'=>'Ada juga pinggan berisi makanan dan garpu di atasnya.','order'=>267],
            ['start_time'=>855.960,'end_time'=>861.540,'target_text'=>'The floor is light-colored and looks like marble or stone.','source_text'=>'Lantainya berwarna cerah dan kelihatan seperti marmar atau batu.','order'=>268],
            ['start_time'=>861.640,'end_time'=>865.900,'target_text'=>'There is a small brown mat on the floor near the sink.','source_text'=>'Ada tikar kecil berwarna coklat di lantai berhampiran sinki.','order'=>269],
            ['start_time'=>866.000,'end_time'=>869.820,'target_text'=>'The kitchen feels modern, organized, and comfortable.','source_text'=>'Dapur ini terasa moden, teratur, dan selesa.','order'=>270],
            ['start_time'=>869.920,'end_time'=>874.460,'target_text'=>'It looks like someone was recently cooking or eating there.','source_text'=>'Kelihatan seperti seseorang baru sahaja memasak atau makan di sana.','order'=>271],
            ['start_time'=>874.560,'end_time'=>878.700,'target_text'=>'That\'s the end of the pronunciation and accent training segment.','source_text'=>'Itulah penghujung segmen latihan sebutan dan loghat.','order'=>272],
            ['start_time'=>878.800,'end_time'=>881.900,'target_text'=>'Don\'t just watch this lesson and forget it.','source_text'=>'Jangan sekadar tengok pelajaran ini dan lupa.','order'=>273],
            ['start_time'=>882.000,'end_time'=>889.220,'target_text'=>'Get the workbook for this video on my website and practice everything from the lesson more deeply.','source_text'=>'Dapatkan buku kerja untuk video ini di laman web saya dan praktikkan semua perkara dari pelajaran ini dengan lebih mendalam.','order'=>274],
            ['start_time'=>889.320,'end_time'=>898.940,'target_text'=>'Inside, you\'ll review the grammar, vocabulary, tenses, sentence patterns, comprehension questions, and real English from this','source_text'=>'Di dalamnya, anda akan mengulang kaji tatabahasa, kosa kata, kala, pola ayat, soalan pemahaman, dan Bahasa Inggeris nyata dari video ini','order'=>275],
            ['start_time'=>899.040,'end_time'=>903.380,'target_text'=>'video with clear explanations and exercises.','source_text'=>'dengan penjelasan dan latihan yang jelas.','order'=>276],
            ['start_time'=>903.480,'end_time'=>908.660,'target_text'=>'Watching helps you understand, but practicing helps you remember.','source_text'=>'Menonton membantu anda faham, tapi berlatih membantu anda ingat.','order'=>277],
            ['start_time'=>908.760,'end_time'=>913.940,'target_text'=>'And when you buy five or more workbooks, you automatically get 30% off at checkout.','source_text'=>'Dan apabila anda beli lima atau lebih buku kerja, anda secara automatik mendapat diskaun 30% semasa pembayaran.','order'=>278],
            ['start_time'=>914.040,'end_time'=>917.840,'target_text'=>'The link is in the description or at vulcaenglish.com.','source_text'=>'Pautan ada dalam penerangan atau di vulcaenglish.com.','order'=>279],
            ['start_time'=>918.000,'end_time'=>921.060,'target_text'=>'Now, let\'s continue with the cleaning of the kitchen.','source_text'=>'Sekarang, jom kita teruskan dengan mengemas dapur.','order'=>280],
            ['start_time'=>921.160,'end_time'=>922.780,'target_text'=>'I\'ll be cleaning the whole kitchen.','source_text'=>'Saya akan kemas keseluruhan dapur.','order'=>281],
            ['start_time'=>922.880,'end_time'=>924.100,'target_text'=>'It\'s probably boring for you guys.','source_text'=>'Mungkin membosankan bagi korang.','order'=>282],
            ['start_time'=>924.200,'end_time'=>927.940,'target_text'=>'It\'ll be a second, but for me it\'ll be a couple minutes.','source_text'=>'Bagi korang ia sekejap, tapi bagi saya ia beberapa minit.','order'=>283],
            ['start_time'=>928.040,'end_time'=>929.900,'target_text'=>'Very clean kitchen.','source_text'=>'Dapur yang sangat bersih.','order'=>284],
            ['start_time'=>930.000,'end_time'=>932.580,'target_text'=>'So, you can see I\'ve cleaned the whole kitchen here.','source_text'=>'Jadi, anda boleh lihat saya dah kemas keseluruhan dapur di sini.','order'=>285],
            ['start_time'=>932.680,'end_time'=>933.940,'target_text'=>'The sink\'s all clean.','source_text'=>'Sinki pun dah bersih.','order'=>286],
            ['start_time'=>934.040,'end_time'=>936.100,'target_text'=>'I wiped the counters with this rag.','source_text'=>'Saya sapu kaunter dengan kain buruk ini.','order'=>287],
            ['start_time'=>936.200,'end_time'=>938.700,'target_text'=>'This is a rag, and I wiped the counters with it.','source_text'=>'Ini adalah kain buruk, dan saya sapu kaunter dengannya.','order'=>288],
            ['start_time'=>938.800,'end_time'=>941.620,'target_text'=>'So, you can see the counters are very shiny, very shiny.','source_text'=>'Jadi, anda boleh lihat kaunternya sangat berkilat, sangat berkilat.','order'=>289],
            ['start_time'=>941.720,'end_time'=>945.180,'target_text'=>'I left that because I\'m going to let it cool down before I pack it away.','source_text'=>'Saya biarkan itu kerana saya nak biarkan ia sejuk dulu sebelum saya simpan.','order'=>290],
            ['start_time'=>945.280,'end_time'=>947.940,'target_text'=>'And here, you can see this is a stain.','source_text'=>'Dan di sini, anda boleh lihat ini adalah tanda kotoran.','order'=>291],
            ['start_time'=>948.040,'end_time'=>949.340,'target_text'=>'I believe this is paint.','source_text'=>'Saya percaya ini adalah cat.','order'=>292],
            ['start_time'=>949.440,'end_time'=>950.100,'target_text'=>'This wasn\'t us.','source_text'=>'Ini bukan kerja kami.','order'=>293],
            ['start_time'=>950.200,'end_time'=>957.300,'target_text'=>'It was here when we moved in, but this looks like a paint stain on these cupboards, on the bottom here, on the bottom row','source_text'=>'Ia memang ada di sini bila kami pindah masuk, tapi ini kelihatan seperti tanda cat pada almari dapur ini, di bahagian bawah, di baris bawah','order'=>294],
            ['start_time'=>957.400,'end_time'=>958.260,'target_text'=>'of cupboards.','source_text'=>'almari.','order'=>295],
            ['start_time'=>958.360,'end_time'=>964.420,'target_text'=>'And we have this big water jug because I don\'t think you can drink water from the tap here.','source_text'=>'Dan kami ada jug air besar ini kerana saya rasa air paip di sini tidak boleh diminum.','order'=>296],
            ['start_time'=>964.520,'end_time'=>965.740,'target_text'=>'I think you\'ll get sick.','source_text'=>'Saya rasa anda akan sakit.','order'=>297],
            ['start_time'=>965.840,'end_time'=>971.660,'target_text'=>'So, we each have one of those big 5-gallon things of water so that we don\'t get sick.','source_text'=>'Jadi, kami masing-masing ada satu tong air 5 galun yang besar supaya kami tidak sakit.','order'=>298],
            ['start_time'=>971.760,'end_time'=>975.060,'target_text'=>'But yeah, right now >> [sighs] >> I\'m just chilling on the sofa.','source_text'=>'Tapi ya, sekarang >> [mengeluh] >> saya sedang bersantai di sofa.','order'=>299],
            ['start_time'=>975.160,'end_time'=>980.460,'target_text'=>'I just ate, and I think it\'s like healthy and a good thing to like go on a walk after you eat.','source_text'=>'Saya baru habis makan, dan saya rasa ia sihat dan baik untuk berjalan-jalan selepas makan.','order'=>300],
            ['start_time'=>980.560,'end_time'=>983.660,'target_text'=>'Like low-key I\'ve been getting more into like like fitness.','source_text'=>'Belakangan ini saya semakin minat dengan kecergasan.','order'=>301],
            ['start_time'=>983.760,'end_time'=>988.020,'target_text'=>'I mean, I\'ve always like kind of been in and out of the gym since I was like 18.','source_text'=>'Maksud saya, saya memang dah pergi ke gimnasium dari umur 18 tahun.','order'=>302],
            ['start_time'=>988.120,'end_time'=>989.260,'target_text'=>'I\'m 23 now, by the way.','source_text'=>'Saya sekarang umur 23, by the way.','order'=>303],
            ['start_time'=>989.360,'end_time'=>995.860,'target_text'=>'Since I was 18, but I was really into the gym when I was in university since I had just had such easy access.','source_text'=>'Sejak umur 18, tapi saya memang rajin ke gimnasium masa universiti kerana akses yang mudah.','order'=>304],
            ['start_time'=>995.960,'end_time'=>1001.780,'target_text'=>'But after university and I was like starting to travel and work and like it was just hard to stay consistent.','source_text'=>'Tapi selepas universiti dan saya mula berjalan-jalan dan bekerja, ia agak susah untuk kekal konsisten.','order'=>305],
            ['start_time'=>1001.880,'end_time'=>1008.580,'target_text'=>'But yeah, now I\'m going back into the gym consistently, and I\'ve been seeing on my TikTok For You page, it\'s just been a lot','source_text'=>'Tapi ya, sekarang saya kembali ke gimnasium secara konsisten, dan saya nampak di halaman TikTok For You saya, ia banyak','order'=>306],
            ['start_time'=>1008.680,'end_time'=>1014.420,'target_text'=>'of fitness stuff, and people have been saying, "Oh, you should go on like a walk after you eat like 10 to 15 minutes cuz it','source_text'=>'tentang kecergasan, dan orang cakap, \'Oh, anda patut berjalan-jalan selepas makan lebih kurang 10 hingga 15 minit sebab ia','order'=>307],
            ['start_time'=>1014.520,'end_time'=>1020.660,'target_text'=>'helps with digestion, but also helps with like like recovery and building muscle if you\'re going to the gym.','source_text'=>'membantu pencernaan, dan juga membantu pemulihan dan pembinaan otot kalau anda ke gimnasium.','order'=>308],
            ['start_time'=>1020.760,'end_time'=>1025.820,'target_text'=>'And if you\'re not, it just feels good because you kind of just digest that food a little bit as you walk, and it feels better.','source_text'=>'Dan kalau tidak pun, ia terasa baik kerana anda mencerna makanan sambil berjalan, dan terasa lebih baik.','order'=>309],
            ['start_time'=>1025.920,'end_time'=>1032.700,'target_text'=>'So, I think I might go out for a walk and walk around this area around us and bring you guys with me.','source_text'=>'Jadi, saya rasa saya mungkin akan keluar berjalan-jalan dan pusing kawasan sekitar sini dan bawa korang bersama.','order'=>310],
            ['start_time'=>1032.800,'end_time'=>1036.020,'target_text'=>'So, let\'s stop sitting on the sofa and resting.','source_text'=>'Jadi, jom kita berhenti duduk di sofa dan berehat.','order'=>311],
            ['start_time'=>1036.120,'end_time'=>1037.740,'target_text'=>'Although this is a really nice sofa.','source_text'=>'Walaupun sofa ini memang cantik.','order'=>312],
            ['start_time'=>1037.840,'end_time'=>1038.820,'target_text'=>'It\'s so long.','source_text'=>'Ia sangat panjang.','order'=>313],
            ['start_time'=>1038.920,'end_time'=>1042.940,'target_text'=>'Like I could just lay down on it and stretch out my whole body and I\'ll still have room.','source_text'=>'Macam saya boleh berbaring dan regangkan seluruh badan dan masih ada ruang.','order'=>314],
            ['start_time'=>1043.040,'end_time'=>1045.940,'target_text'=>'But, I think I\'ll go out and walk down a little bit.','source_text'=>'Tapi, saya rasa saya nak keluar dan berjalan sedikit.','order'=>315],
            ['start_time'=>1046.040,'end_time'=>1050.460,'target_text'=>'I think there is like a GS25 that\'s a Korean convenience store just down the road here.','source_text'=>'Saya rasa ada GS25 — itu kedai serbaneka Korea — betul-betul di hujung jalan ni.','order'=>316],
            ['start_time'=>1050.560,'end_time'=>1052.460,'target_text'=>'So, I\'ll go check that out.','source_text'=>'Jadi, saya akan pergi tengok.','order'=>317],
            ['start_time'=>1052.560,'end_time'=>1054.740,'target_text'=>'>> Hey, we\'re outside now.','source_text'=>'Eh, kita dah ada di luar sekarang.','order'=>318],
            ['start_time'=>1054.840,'end_time'=>1055.700,'target_text'=>'As you can see.','source_text'=>'Seperti yang anda boleh lihat.','order'=>319],
            ['start_time'=>1055.800,'end_time'=>1058.260,'target_text'=>'>> Okay, so I didn\'t actually have my mic on that whole time.','source_text'=>'Okay, jadi saya tak pasang mikrofon saya sepanjang masa tu.','order'=>320],
            ['start_time'=>1058.360,'end_time'=>1061.460,'target_text'=>'So, any audio I said did not get recorded.','source_text'=>'Jadi, apa sahaja audio yang saya cakap tidak dapat dirakam.','order'=>321],
            ['start_time'=>1061.560,'end_time'=>1067.020,'target_text'=>'But, here you can see there are a lot of flower pots with trees and plants growing in them.','source_text'=>'Tapi, di sini anda boleh lihat ada banyak pasu bunga dengan pokok dan tumbuhan.','order'=>322],
            ['start_time'=>1067.120,'end_time'=>1071.740,'target_text'=>'And right now we\'re walking to the convenience store and uh it\'s a little far.','source_text'=>'Dan sekarang kami sedang berjalan ke kedai serbaneka dan ia agak jauh.','order'=>323],
            ['start_time'=>1071.840,'end_time'=>1075.340,'target_text'=>'Leon said it wasn\'t that far, but we low-key have been walking for >> I said 5-minute walk.','source_text'=>'Leon kata ia tidak jauh, tapi kita dah lama berjalan >> Saya kata 5 minit berjalan.','order'=>324],
            ['start_time'=>1075.440,'end_time'=>1076.420,'target_text'=>'>> for a minute here.','source_text'=>'>> dah sejak tadi.','order'=>325],
            ['start_time'=>1076.520,'end_time'=>1078.340,'target_text'=>'Now, we\'re really like in a neighborhood area.','source_text'=>'Sekarang, kita betul-betul berada di kawasan kejiranan.','order'=>326],
            ['start_time'=>1078.440,'end_time'=>1080.460,'target_text'=>'So, what were you saying about the weather here?','source_text'=>'Jadi, apa yang anda kata tentang cuaca di sini?','order'=>327],
            ['start_time'=>1080.560,'end_time'=>1084.940,'target_text'=>'>> As you can see, it\'s like kind of overcast and that\'s cuz we\'re approaching the rainy season.','source_text'=>'Seperti yang anda boleh lihat, ia agak berawan dan itu kerana kita menghampiri musim hujan.','order'=>328],
            ['start_time'=>1085.040,'end_time'=>1087.340,'target_text'=>'So, yesterday we had a lot of rain.','source_text'=>'Jadi, semalam ada banyak hujan.','order'=>329],
            ['start_time'=>1087.440,'end_time'=>1088.540,'target_text'=>'It was really loud.','source_text'=>'Ia sangat kuat bunyinya.','order'=>330],
            ['start_time'=>1088.640,'end_time'=>1093.380,'target_text'=>'I was actually wondering what the sound was and then I looked outside and I could see the rain coming down.','source_text'=>'Saya sebenarnya tertanya-tanya bunyi apa itu dan kemudian saya tengok keluar dan saya boleh nampak hujan turun.','order'=>331],
            ['start_time'=>1093.480,'end_time'=>1096.860,'target_text'=>'So, now that we\'re in the rainy season, it\'s going to cool down a little bit.','source_text'=>'Jadi, sekarang kita dah masuk musim hujan, cuaca akan turun sikit.','order'=>332],
            ['start_time'=>1096.960,'end_time'=>1098.500,'target_text'=>'It\'s not that hot right now.','source_text'=>'Sekarang tidak terlalu panas.','order'=>333],
            ['start_time'=>1098.600,'end_time'=>1103.060,'target_text'=>'So, it\'s actually nice to walk outside and it\'s like what, 3:00 right now?','source_text'=>'Jadi, sebenarnya seronok untuk berjalan di luar dan sekarang kira-kira pukul 3 kan?','order'=>334],
            ['start_time'=>1103.160,'end_time'=>1103.620,'target_text'=>'>> Yeah.','source_text'=>'Ya.','order'=>335],
            ['start_time'=>1103.720,'end_time'=>1105.540,'target_text'=>'>> So, for 3:00 p.m.','source_text'=>'Jadi, untuk pukul 3 petang.','order'=>336],
            ['start_time'=>1105.640,'end_time'=>1107.140,'target_text'=>'it\'s really nice outside.','source_text'=>'cuaca di luar memang seronok.','order'=>337],
            ['start_time'=>1107.240,'end_time'=>1109.700,'target_text'=>'I\'m not super sweaty or anything, but uh yeah.','source_text'=>'Saya tidak terlalu berpeluh atau apa-apa, tapi ya.','order'=>338],
            ['start_time'=>1109.800,'end_time'=>1110.660,'target_text'=>'Rainy season.','source_text'=>'Musim hujan.','order'=>339],
            ['start_time'=>1110.760,'end_time'=>1113.100,'target_text'=>'When we were here last week and >> Hello.','source_text'=>'Masa kita ada di sini minggu lepas dan >> Helo.','order'=>340],
            ['start_time'=>1113.200,'end_time'=>1113.600,'target_text'=>'>> Hello.','source_text'=>'Helo.','order'=>341],
            ['start_time'=>1113.600,'end_time'=>1114.000,'target_text'=>'>> How are you?','source_text'=>'Apa khabar?','order'=>342],
            ['start_time'=>1114.080,'end_time'=>1118.080,'target_text'=>'>> When we were here last week and uh >> Yeah.','source_text'=>'Masa kita ada di sini minggu lepas dan >> Ya.','order'=>343],
            ['start_time'=>1118.480,'end_time'=>1120.280,'target_text'=>'Yeah.','source_text'=>'Ya.','order'=>344],
            ['start_time'=>1122.640,'end_time'=>1125.300,'target_text'=>'When we were here last week and','source_text'=>'Masa kita ada di sini minggu lepas dan','order'=>345],
            ['start_time'=>1125.400,'end_time'=>1125.720,'target_text'=>'So, yeah.','source_text'=>'Jadi, ya.','order'=>346],
            ['start_time'=>1125.720,'end_time'=>1128.380,'target_text'=>'This little kid spoke really good English, fluent.','source_text'=>'Budak kecil ni cakap Bahasa Inggeris dengan sangat baik, fasih.','order'=>347],
            ['start_time'=>1128.480,'end_time'=>1129.780,'target_text'=>'>> Oh, he sounded like American.','source_text'=>'Oh, dia bunyi macam orang Amerika.','order'=>348],
            ['start_time'=>1129.880,'end_time'=>1133.020,'target_text'=>'>> There\'s a lot of English schools around here, so it makes sense, but Oh, yeah.','source_text'=>'Ada banyak sekolah Bahasa Inggeris di sekitar sini, jadi masuk akal lah, tapi Oh, ya.','order'=>349],
            ['start_time'=>1133.120,'end_time'=>1134.460,'target_text'=>'Here\'s the GS25.','source_text'=>'Ini GS25-nya.','order'=>350],
            ['start_time'=>1134.560,'end_time'=>1136.180,'target_text'=>'It\'s kind of like in the middle of nowhere.','source_text'=>'Ia macam terletak di tengah-tengah kawasan yang agak sunyi.','order'=>351],
            ['start_time'=>1136.280,'end_time'=>1137.380,'target_text'=>'>> Actually is like a big one.','source_text'=>'Sebenarnya ia yang besar.','order'=>352],
            ['start_time'=>1137.480,'end_time'=>1139.100,'target_text'=>'I thought it would be small.','source_text'=>'Saya ingat ia akan kecil.','order'=>353],
            ['start_time'=>1139.200,'end_time'=>1144.220,'target_text'=>'So, anyway, Leon was just saying that it\'s about to enter rainy season and that\'s why it\'s gray.','source_text'=>'Jadi, anyway, Leon baru cakap yang musim hujan nak masuk dan sebab tu langit kelabu.','order'=>354],
            ['start_time'=>1144.320,'end_time'=>1147.340,'target_text'=>'>> Yeah, and cooler outside, which is a lot nicer.','source_text'=>'Ya, dan di luar lebih sejuk, yang memang lebih seronok.','order'=>355],
            ['start_time'=>1147.440,'end_time'=>1149.620,'target_text'=>'>> Yeah, but now we\'re in the GS25 here.','source_text'=>'Ya, tapi sekarang kita dah dalam GS25.','order'=>356],
            ['start_time'=>1149.720,'end_time'=>1151.140,'target_text'=>'It\'s actually super nice.','source_text'=>'Ia memang sangat bagus.','order'=>357],
            ['start_time'=>1151.240,'end_time'=>1152.660,'target_text'=>'>> Yeah, I came here this morning.','source_text'=>'Ya, saya datang sini pagi tadi.','order'=>358],
            ['start_time'=>1152.760,'end_time'=>1153.860,'target_text'=>'>> It\'s really big, too.','source_text'=>'Ia besar juga.','order'=>359],
            ['start_time'=>1153.960,'end_time'=>1155.900,'target_text'=>'>> one of these, onigiri.','source_text'=>'Satu dari yang ni, onigiri.','order'=>360],
            ['start_time'=>1156.000,'end_time'=>1157.500,'target_text'=>'Is this onigiri or kimbap?','source_text'=>'Ini onigiri atau kimbap?','order'=>361],
            ['start_time'=>1157.600,'end_time'=>1162.140,'target_text'=>'>> It\'s kimbap cuz it\'s >> What are they in the comments fighting over that?','source_text'=>'Ini kimbap sebab ia >> Apa yang mereka bergaduh dalam komen tu?','order'=>362],
            ['start_time'=>1162.240,'end_time'=>1164.220,'target_text'=>'>> But yeah, I think now I just low-key need a drink.','source_text'=>'Tapi ya, saya rasa saya nak minum sesuatu sekarang.','order'=>363],
            ['start_time'=>1164.320,'end_time'=>1166.260,'target_text'=>'I think I\'ll get my favorite electrolyte drink.','source_text'=>'Saya rasa saya akan ambil minuman elektrolit kegemaran saya.','order'=>364],
            ['start_time'=>1166.360,'end_time'=>1167.940,'target_text'=>'I think you should get one of these, too.','source_text'=>'Saya rasa anda patut ambil satu juga.','order'=>365],
            ['start_time'=>1168.040,'end_time'=>1169.540,'target_text'=>'No, just chicken feet, [snorts] bro.','source_text'=>'Tidak, kaki ayam sahaja, kawan.','order'=>366],
            ['start_time'=>1169.640,'end_time'=>1170.940,'target_text'=>'I\'m good, dude.','source_text'=>'Saya okay, kawan.','order'=>367],
            ['start_time'=>1171.040,'end_time'=>1176.500,'target_text'=>'I really hope this is an electrolyte drink and it\'s not like actually just like pure sugar because I low-key have been drinking','source_text'=>'Saya betul-betul harap ini adalah minuman elektrolit dan bukan sekadar gula tulen kerana saya memang banyak minum','order'=>368],
            ['start_time'=>1176.600,'end_time'=>1179.180,'target_text'=>'this a lot, but it does say hydrate.','source_text'=>'ini, tapi ia memang tertulis \'hydrate\'.','order'=>369],
            ['start_time'=>1179.280,'end_time'=>1182.380,'target_text'=>'And it also says B3, B6, B12, so >> Yeah.','source_text'=>'Dan ia juga ada B3, B6, B12, jadi >> Ya.','order'=>370],
            ['start_time'=>1182.480,'end_time'=>1182.880,'target_text'=>'>> Let\'s hope.','source_text'=>'Jom harap-harap.','order'=>371],
            ['start_time'=>1182.880,'end_time'=>1183.580,'target_text'=>'Check the macros.','source_text'=>'Semak kandungan nutrisinya.','order'=>372],
            ['start_time'=>1183.680,'end_time'=>1186.080,'target_text'=>'Hope it\'s good for me.','source_text'=>'Harap ia baik untuk saya.','order'=>373],
            ['start_time'=>1186.870,'end_time'=>1190.860,'target_text'=>'>> [music] >> As I was saying there, I don\'t know if you heard me because of the copyrighted music.','source_text'=>'>> [muzik] >> Seperti yang saya cakap tadi, saya tidak tahu kalau korang dengar saya sebab muzik berhak cipta tu.','order'=>374],
            ['start_time'=>1190.960,'end_time'=>1192.060,'target_text'=>'I kind of forgot about that.','source_text'=>'Saya macam terlupa pasal tu.','order'=>375],
            ['start_time'=>1192.160,'end_time'=>1197.740,'target_text'=>'But I was just saying Kuala Lumpur is the city with the most intense thunderstorms I\'ve ever experienced.','source_text'=>'Tapi saya baru cakap Kuala Lumpur adalah bandar dengan ribut petir paling kuat yang pernah saya lalami.','order'=>376],
            ['start_time'=>1197.840,'end_time'=>1200.100,'target_text'=>'They\'re so loud and so frequent.','source_text'=>'Ia sangat kuat dan sangat kerap berlaku.','order'=>377],
            ['start_time'=>1200.200,'end_time'=>1205.940,'target_text'=>'And if you\'re scared of thunder and like loud noises and thunderstorms, then you need like earplugs or like blindfolds or','source_text'=>'Dan kalau anda takut dengan guruh dan bunyi kuat dan ribut petir, anda perlukan penyumbat telinga atau penutup mata atau','order'=>378],
            ['start_time'=>1206.040,'end_time'=>1209.380,'target_text'=>'something cuz it\'s a really like stormy city.','source_text'=>'sesuatu kerana ia memang bandar yang sangat berhujan.','order'=>379],
            ['start_time'=>1209.480,'end_time'=>1210.420,'target_text'=>'But I like that vibe.','source_text'=>'Tapi saya suka suasana tu.','order'=>380],
            ['start_time'=>1210.520,'end_time'=>1211.340,'target_text'=>'I love that vibe.','source_text'=>'Saya suka sangat suasana tu.','order'=>381],
            ['start_time'=>1211.440,'end_time'=>1218.620,'target_text'=>'I love like really loud thunderstorms that shake your entire home and it\'s just like Oh, I love that.','source_text'=>'Saya suka ribut petir yang sangat kuat yang menggegar seluruh rumah dan rasa macam — Oh, saya suka tu.','order'=>382],
            ['start_time'=>1218.720,'end_time'=>1219.620,'target_text'=>'My favorite.','source_text'=>'Kegemaran saya.','order'=>383],
            ['start_time'=>1219.720,'end_time'=>1223.980,'target_text'=>'Like opening the window, watching outside, or even going outside, walking around, going swimming.','source_text'=>'Macam buka tingkap, tengok ke luar, atau bahkan keluar, berjalan-jalan, pergi berenang.','order'=>384],
            ['start_time'=>1224.080,'end_time'=>1225.060,'target_text'=>'Low-key vibes.','source_text'=>'Suasana yang best.','order'=>385],
            ['start_time'=>1225.160,'end_time'=>1225.980,'target_text'=>'I like it.','source_text'=>'Saya suka.','order'=>386],
            ['start_time'=>1226.080,'end_time'=>1231.380,'target_text'=>'And now we\'re walking to Family Mart, which is just around the corner, according to Leon.','source_text'=>'Dan sekarang kami berjalan ke Family Mart, yang ada betul-betul di sebalik penjuru, kata Leon.','order'=>387],
            ['start_time'=>1231.480,'end_time'=>1232.540,'target_text'=>'What did you get?','source_text'=>'Apa yang awak dapat?','order'=>388],
            ['start_time'=>1232.640,'end_time'=>1235.060,'target_text'=>'>> Peanut and coconut coating.','source_text'=>'Salutan kacang tanah dan kelapa.','order'=>389],
            ['start_time'=>1235.160,'end_time'=>1236.980,'target_text'=>'Peanut cracker, that\'s what they call it.','source_text'=>'Keropok kacang tanah, begitulah panggilannya.','order'=>390],
            ['start_time'=>1237.080,'end_time'=>1238.020,'target_text'=>'>> Peanut cracker?','source_text'=>'Keropok kacang tanah?','order'=>391],
            ['start_time'=>1238.120,'end_time'=>1238.860,'target_text'=>'>> It\'s really good.','source_text'=>'Ia sangat sedap.','order'=>392],
            ['start_time'=>1238.960,'end_time'=>1239.580,'target_text'=>'>> Is it good?','source_text'=>'Sedap ke?','order'=>393],
            ['start_time'=>1239.680,'end_time'=>1241.420,'target_text'=>'How would you describe it?','source_text'=>'Macam mana anda nak huraikannya?','order'=>394],
            ['start_time'=>1241.520,'end_time'=>1242.900,'target_text'=>'>> It\'s really crunchy.','source_text'=>'Ia sangat rangup.','order'=>395],
            ['start_time'=>1243.000,'end_time'=>1245.860,'target_text'=>'I like anything that\'s peanut flavor, so this is a hit for me.','source_text'=>'Saya suka apa sahaja yang berperisa kacang tanah, jadi ini memang kena selera saya.','order'=>396],
            ['start_time'=>1245.960,'end_time'=>1247.860,'target_text'=>'And the coconut is not super overpowering.','source_text'=>'Dan kelapanya tidak terlalu kuat rasanya.','order'=>397],
            ['start_time'=>1247.960,'end_time'=>1248.980,'target_text'=>'It\'s pretty subtle.','source_text'=>'Ia agak halus.','order'=>398],
            ['start_time'=>1249.080,'end_time'=>1250.420,'target_text'=>'It\'s actually really nice.','source_text'=>'Ia sebenarnya sangat sedap.','order'=>399],
            ['start_time'=>1250.520,'end_time'=>1251.620,'target_text'=>'You see, this is what they look like.','source_text'=>'Anda tengok, ini rupa-rupanya.','order'=>400],
            ['start_time'=>1251.720,'end_time'=>1254.580,'target_text'=>'Basically, they look like peanuts and they have like a powder coating on them.','source_text'=>'Pada asasnya, ia kelihatan seperti kacang tanah dan ada lapisan serbuk di atasnya.','order'=>401],
            ['start_time'=>1254.680,'end_time'=>1256.940,'target_text'=>'I think it\'s like some sort of powder sugar.','source_text'=>'Saya rasa ia sejenis gula serbuk.','order'=>402],
            ['start_time'=>1257.040,'end_time'=>1259.740,'target_text'=>'And they\'re not really hard, but they have a lot of crunch to them.','source_text'=>'Ia tidak terlalu keras, tapi ada banyak kerangan.','order'=>403],
            ['start_time'=>1259.840,'end_time'=>1261.100,'target_text'=>'They\'re kind of airy, actually.','source_text'=>'Ia sebenarnya agak berangin.','order'=>404],
            ['start_time'=>1261.200,'end_time'=>1264.000,'target_text'=>'I\'ll see if I can bite one in half.','source_text'=>'Saya cuba gigit separuh.','order'=>405],
            ['start_time'=>1265.360,'end_time'=>1267.540,'target_text'=>'Oh, they\'re hollow.','source_text'=>'Oh, ia kosong.','order'=>406],
            ['start_time'=>1267.640,'end_time'=>1268.620,'target_text'=>'Bro, I think I got scammed.','source_text'=>'Kawan, saya rasa saya kena tipu.','order'=>407],
            ['start_time'=>1268.720,'end_time'=>1269.820,'target_text'=>'There\'s no peanut in here.','source_text'=>'Tiada kacang tanah dalam sini.','order'=>408],
            ['start_time'=>1269.920,'end_time'=>1271.220,'target_text'=>'>> Bro, you just got scammed.','source_text'=>'Kawan, awak kena tipu.','order'=>409],
            ['start_time'=>1271.320,'end_time'=>1274.660,'target_text'=>'These right here are green trash bins.','source_text'=>'Ini di sini adalah tong sampah hijau.','order'=>410],
            ['start_time'=>1274.760,'end_time'=>1275.620,'target_text'=>'Green trash bins.','source_text'=>'Tong sampah hijau.','order'=>411],
            ['start_time'=>1275.720,'end_time'=>1283.300,'target_text'=>'So, you put your trash here, and then usually someone, most of the time it\'s the city, comes and throws the trash out, usually','source_text'=>'Jadi, anda letak sampah di sini, dan biasanya seseorang, kebanyakan masa adalah pihak bandar, datang dan buang sampah, biasanya','order'=>412],
