            ['start_time'=>1324.760,'end_time'=>1326.220,'target_text'=>'Let me know in the comments.','source_text'=>'Beritahu saya dalam komen.','order'=>429],
            ['start_time'=>1326.320,'end_time'=>1327.820,'target_text'=>'Yo, what are you working on?','source_text'=>'Eh, apa yang kau tengah buat tu?','order'=>430],
            ['start_time'=>1327.920,'end_time'=>1329.820,'target_text'=>'>> Yo, I\'m working on my channel right now.','source_text'=>'Eh, aku tengah kerja untuk saluran aku sekarang.','order'=>431],
            ['start_time'=>1329.920,'end_time'=>1330.500,'target_text'=>'I just started.','source_text'=>'Baru bermula.','order'=>432],
